window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-45ac05dbaf21965f"]={"versions": [{"id": "FIG-45ac05dbaf21965f", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-2.0-Klassendiagramm (Metamodell-Ausschnitt, AUTOSAR M2-Ebene).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifikation der Metaklassen für die Client/Server-Kommunikation auf Provider-Ebene innerhalb des <em>AUTOSAR Behavioral Modeling</em> (Frühphase/Release R2.1.20). Es modelliert die strukturelle Verankerung von Kommunikationsparametern (<code>ServerComSpec</code>) an Bereitstellungs-Ports (<code>PPortPrototype</code>) eines Software-Komponenten-Typs (<code>ComponentType</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Components::ComponentType</code></strong> (<code>«ARElement»</code>, abstrakt):</li>\n<li>Wurzelelement des Software-Designs; aggregiert Ports über die Kompositionsbeziehung <code>+ports</code> (Kardinalität <code>0..*</code>). Rolle an der Komponentenseite: <code>+component</code>.</li>\n<li><strong><code>Components::PortPrototype</code></strong> (<code>«ARElement»</code>, abstrakt):</li>\n<li>Basisklasse aller Komponenten-Ports.</li>\n<li>Eigenschaften/Stereotypen: <code>ExistenceDependsOnProperty</code>, <code>Identifiable</code>, <code>PropertyEvaluator</code>.</li>\n<li><strong><code>Components::PPortPrototype</code></strong>:</li>\n<li>Konkretisierung von <code>PortPrototype</code> als Bereitstellungs-Port (Provided Port / Server-Port).</li>\n<li>Hält per Komposition <code>0..* +comSpec</code> Instanzen vom Typ <code>PPortComSpec</code>.</li>\n<li><strong><code>Communication::PPortComSpec</code></strong> (abstrakt):</li>\n<li>Generalisierte Kommunikationsspezifikation für P-Ports.</li>\n<li>Wird referenziert/importiert durch das Paket <code>BM Environment (from Behavior Modeling)</code>.</li>\n<li><strong><code>Communication::ServerComSpec</code></strong>:</li>\n<li>Spezialisierung von <code>PPortComSpec</code> zur Parametrierung von Client/Server-Schnittstellen auf Provider-Seite.</li>\n<li>Wird via <code>«import»</code> in das Paket <code>BM Environment</code> eingebunden.</li>\n<li><strong>Attribut:</strong> <code>+ queueLength: Int</code> (Definiert die Pufferkapazität für eingehende Client-Aufrufe).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Synchronisations- & Pufferverhalten:</strong> Das Diagramm selbst ist statisch; das Attribut <code>queueLength</code> steuert jedoch direkt die Laufzeitsemantik der RTE:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aufrufeingang:</strong> Ein Client setzt einen synchronen oder asynchronen Aufruf (<code>Rte_Call</code>) gegen eine ClientServer-Operation des Server-Ports ab.</li>\n<li><strong>Warteschlangen-Verarbeitung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist die assoziierte Server-<code>RunnableEntity</code> bereits aktiv oder nicht wiedereintrittsfähig (<code>canBeInvokedConcurrently = false</code>), puffert die RTE den Aufruf (inkl. IN/INOUT-Parametern und Aufrufer-Kontext) in einer FIFO-Warteschlange der Größe <code>queueLength</code>.</li>\n<li><strong><code>queueLength == 1</code>:</strong> Kein oder minimaler Puffer; nachfolgende gleichzeitige Aufrufe werden abgewiesen.</li>\n<li><strong><code>queueLength &gt; 1</code>:</strong> Ermöglicht Entkopplung und Abarbeitung von Lastspitzen (Burst-Anfragen).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Überlauf / Abbruch:</strong> Übersteigt die Anzahl gleichzeitiger/anhängiger Requests den Wert <code>queueLength</code>, meldet die RTE einen Infrastrukturfehler (z. B. <code>RTE_E_LIMIT</code> bzw. <code>RTE_E_TIMEOUT</code>) an den Aufrufer zurück.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE-Codegenerierung:</strong></li>\n<li>Der RTE-Generator wertet <code>ServerComSpec.queueLength</code> aus und dimensioniert statische Puffer (Ringpuffer/Arrays in <code>.bss</code>) sowie OS-Synchronisationsobjekte (z. B. OS-Events, Queues oder Spinlocks bei Multi-Core).</li>\n<li><strong>Speicher-Footprint vs. Robustheit:</strong></li>\n<li>Zu groß gewähltes <code>queueLength</code> führt zu unnötigem statischen RAM-Verbrauch (pro Port/Operation skalierend mit der Bytegröße der Funktionsargumente).</li>\n<li>Zu knapp gewähltes <code>queueLength</code> führt bei asynchronen Server-Aufrufen unter Last zu Pufferüberläufen und Daten-/Aufrufverlusten.</li>\n<li><strong>ARXML-Konfiguration:</strong></li>\n<li>Zu finden im ARXML unter <code>&lt;PROVIDED-COM-SPECS&gt;</code> als <code>&lt;SERVER-COM-SPEC&gt;</code> mit Kindelement <code>&lt;QUEUE-LENGTH&gt;</code>. Fehlt das Element oder ist <code>queueLength = 0</code>, unterstützt die RTE standardmäßig keine Pufferung für diesen Server-Port.</li>\n</ul>"}, {"id": "FIG-13ed7b67478bbd6d", "releases": ["R3.0.7", "R3.1.5", "R3.2.3", "R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-2.0-Klassendiagramm (Metamodell-Ausschnitt, AUTOSAR M2-Ebene).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifikation der Metaklassen für die Client/Server-Kommunikation auf Provider-Ebene innerhalb des <em>AUTOSAR Behavioral Modeling</em> (Frühphase/Release R2.1.20). Es modelliert die strukturelle Verankerung von Kommunikationsparametern (<code>ServerComSpec</code>) an Bereitstellungs-Ports (<code>PPortPrototype</code>) eines Software-Komponenten-Typs (<code>ComponentType</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Components::ComponentType</code></strong> (<code>«ARElement»</code>, abstrakt):</li>\n<li>Wurzelelement des Software-Designs; aggregiert Ports über die Kompositionsbeziehung <code>+ports</code> (Kardinalität <code>0..*</code>). Rolle an der Komponentenseite: <code>+component</code>.</li>\n<li><strong><code>Components::PortPrototype</code></strong> (<code>«ARElement»</code>, abstrakt):</li>\n<li>Basisklasse aller Komponenten-Ports.</li>\n<li>Eigenschaften/Stereotypen: <code>ExistenceDependsOnProperty</code>, <code>Identifiable</code>, <code>PropertyEvaluator</code>.</li>\n<li><strong><code>Components::PPortPrototype</code></strong>:</li>\n<li>Konkretisierung von <code>PortPrototype</code> als Bereitstellungs-Port (Provided Port / Server-Port).</li>\n<li>Hält per Komposition <code>0..* +comSpec</code> Instanzen vom Typ <code>PPortComSpec</code>.</li>\n<li><strong><code>Communication::PPortComSpec</code></strong> (abstrakt):</li>\n<li>Generalisierte Kommunikationsspezifikation für P-Ports.</li>\n<li>Wird referenziert/importiert durch das Paket <code>BM Environment (from Behavior Modeling)</code>.</li>\n<li><strong><code>Communication::ServerComSpec</code></strong>:</li>\n<li>Spezialisierung von <code>PPortComSpec</code> zur Parametrierung von Client/Server-Schnittstellen auf Provider-Seite.</li>\n<li>Wird via <code>«import»</code> in das Paket <code>BM Environment</code> eingebunden.</li>\n<li><strong>Attribut:</strong> <code>+ queueLength: Int</code> (Definiert die Pufferkapazität für eingehende Client-Aufrufe).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Synchronisations- & Pufferverhalten:</strong> Das Diagramm selbst ist statisch; das Attribut <code>queueLength</code> steuert jedoch direkt die Laufzeitsemantik der RTE:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aufrufeingang:</strong> Ein Client setzt einen synchronen oder asynchronen Aufruf (<code>Rte_Call</code>) gegen eine ClientServer-Operation des Server-Ports ab.</li>\n<li><strong>Warteschlangen-Verarbeitung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist die assoziierte Server-<code>RunnableEntity</code> bereits aktiv oder nicht wiedereintrittsfähig (<code>canBeInvokedConcurrently = false</code>), puffert die RTE den Aufruf (inkl. IN/INOUT-Parametern und Aufrufer-Kontext) in einer FIFO-Warteschlange der Größe <code>queueLength</code>.</li>\n<li><strong><code>queueLength == 1</code>:</strong> Kein oder minimaler Puffer; nachfolgende gleichzeitige Aufrufe werden abgewiesen.</li>\n<li><strong><code>queueLength &gt; 1</code>:</strong> Ermöglicht Entkopplung und Abarbeitung von Lastspitzen (Burst-Anfragen).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Überlauf / Abbruch:</strong> Übersteigt die Anzahl gleichzeitiger/anhängiger Requests den Wert <code>queueLength</code>, meldet die RTE einen Infrastrukturfehler (z. B. <code>RTE_E_LIMIT</code> bzw. <code>RTE_E_TIMEOUT</code>) an den Aufrufer zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE-Codegenerierung:</strong></li>\n<li>Der RTE-Generator wertet <code>ServerComSpec.queueLength</code> aus und dimensioniert statische Puffer (Ringpuffer/Arrays in <code>.bss</code>) sowie OS-Synchronisationsobjekte (z. B. OS-Events, Queues oder Spinlocks bei Multi-Core).</li>\n<li><strong>Speicher-Footprint vs. Robustheit:</strong></li>\n<li>Zu groß gewähltes <code>queueLength</code> führt zu unnötigem statischen RAM-Verbrauch (pro Port/Operation skalierend mit der Bytegröße der Funktionsargumente).</li>\n<li>Zu knapp gewähltes <code>queueLength</code> führt bei asynchronen Server-Aufrufen unter Last zu Pufferüberläufen und Daten-/Aufrufverlusten.</li>\n<li><strong>ARXML-Konfiguration:</strong></li>\n<li>Zu finden im ARXML unter <code>&lt;PROVIDED-COM-SPECS&gt;</code> als <code>&lt;SERVER-COM-SPEC&gt;</code> mit Kindelement <code>&lt;QUEUE-LENGTH&gt;</code>. Fehlt das Element oder ist <code>queueLength = 0</code>, unterstützt die RTE standardmäßig keine Pufferung für diesen Server-Port.</li>\n</ul>"}], "trans": [{"from": "FIG-45ac05dbaf21965f", "to": "FIG-13ed7b67478bbd6d", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
